def search_code(
    self,
    query: str,
    max_results: int = 50,
) -> list[str]:
    """
    Search for a text query across source files.

    Returns matching file paths, line numbers,
    and source lines.
    """

    if not query or not query.strip():
        raise ValueError(
            "Search query cannot be empty."
        )

    if max_results < 1:
        raise ValueError(
            "max_results must be at least 1."
        )

    results = []

    query_lower = query.lower()

    for path in sorted(
        self.root.rglob("*")
    ):

        if not path.is_file():
            continue

        if self._is_ignored(path):
            continue

        if (
            path.suffix.lower()
            not in self.SEARCHABLE_EXTENSIONS
        ):
            continue

        try:
            content = path.read_text(
                encoding="utf-8"
            )
        except (
            UnicodeDecodeError,
            OSError,
        ):
            continue

        for line_number, line in enumerate(
            content.splitlines(),
            start=1,
        ):

            if query_lower in line.lower():

                relative_path = (
                    path.relative_to(
                        self.root
                    )
                )

                results.append(
                    f"{relative_path}:"
                    f"{line_number}: "
                    f"{line.strip()}"
                )

                if (
                    len(results)
                    >= max_results
                ):
                    return results

    return results

def get_dependencies(
    relative_path: str,
    max_results: int = 100,
) -> str:
    """
    Return local repository files that a source
    file depends on.
    """

    repository = get_repository()

    indexer = CodeIndexer(
        repository.root
    )

    dependencies = indexer.get_dependencies(
        relative_path,
        max_results,
    )

    if not dependencies:
        return (
            f"No local dependencies found for: "
            f"{relative_path}"
        )

    lines = []

    normalized_source = str(
        relative_path
    ).replace(
        "\\",
        "/",
    )

    for dependency in dependencies:

        lines.append(
            f"{normalized_source} -> "
            f"{dependency['path']} "
            f"[{dependency['dependency_type']}] "
            f"line {dependency['line']}"
        )

    return "\n".join(lines)

def find_usages(
    symbol_name: str,
    max_results: int = 100,
) -> str:
    """
    Find references to a symbol using the
    indexed repository.
    """

    repository = get_repository()

    indexer = CodeIndexer(
        repository.root
    )

    usages = indexer.find_usages(
        symbol_name,
        max_results,
    )

    if not usages:
        return (
            f"No usages found for: {symbol_name}\n"
            "Run index_repository() first."
