        lines.append(
            f"{usage['path']}:"
            f"{usage['line']} "
            f"[{usage['reference_type']}] "
            f"{usage['symbol_name']}"
        )

    return "\n".join(lines)

def find_references(
    self,
    relative_path: str,
) -> list[dict]:
    """
    Extract meaningful symbol references from a Python file.
    """

    path = self._resolve_python_file(relative_path)

    source = path.read_text(
        encoding="utf-8"
    )

    try:
        tree = ast.parse(source)
    except SyntaxError as exc:
        raise ValueError(
            f"Could not parse {relative_path}: {exc}"
        )

    references = []

    for node in ast.walk(tree):

        # Function/class calls:
        #
        # get_repository()
        # Repository(...)
        #
        if isinstance(node, ast.Call):

            target = node.func

            if isinstance(target, ast.Name):

                references.append({
                    "symbol_name": target.id,
                    "line": target.lineno,
                    "reference_type": "call",
                })

            elif isinstance(target, ast.Attribute):

                references.append({
                    "symbol_name": target.attr,
                    "line": target.lineno,
                    "reference_type": "method_call",
                })

        # Imports:
        #
        # from repository import Repository
        #
        elif isinstance(node, ast.Import):

            for alias in node.names:

                references.append({
                    "symbol_name": alias.name,
                    "line": node.lineno,
                    "reference_type": "import",
                })

        elif isinstance(node, ast.ImportFrom):

            for alias in node.names:

                references.append({
                    "symbol_name": alias.name,
                    "line": node.lineno,
                    "reference_type": "import",
                })

        # Attribute access:
        #
        # repository.root
        #
        elif isinstance(node, ast.Attribute):

        # Avoid duplicating attributes that were already
        # recorded as method calls.
        if isinstance(node.ctx, ast.Load):

            parent_is_call = False

            for parent in ast.walk(tree):

                if (
                    isinstance(parent, ast.Call)
                    and parent.func is node
                ):
                    parent_is_call = True
                    break

            if not parent_is_call:

                references.append({
                    "symbol_name": node.attr,
                    "line": node.lineno,
                    "reference_type": "attribute",
                })

    # Direct symbol references:
    #
    # Repository
    # analyzer
    #
    elif isinstance(node, ast.Name):

        # Skip names that are function calls.
        parent_is_call = False

        for parent in ast.walk(tree):

            if (
                isinstance(parent, ast.Call)
                and parent.func is node
            ):
                parent_is_call = True
                break

        if not parent_is_call:

            references.append({
                "symbol_name": node.id,
                "line": node.lineno,
                "reference_type": "reference",
            })

return references

def search_symbols(
    query: str,
    max_results: int = 100,
) -> str:
    """
    Search the SQLite code index for classes,
    functions, methods and imports.
    """

    repository = get_repository()

    indexer = CodeIndexer(
        repository.root
    )

    results = indexer.search_symbols(
        query,
        max_results,
    )

    if not results:
        return (
            f"No indexed symbols found for: {query}\n"
            "Run index_repository() first."
        )

    lines = []

    for symbol in results:

        lines.append(
            f"{symbol['path']}: "
            f"{symbol['type']} "
            f"{symbol['qualified_name']} "
            f"(lines "
            f"{symbol['line']}-"
            f"{symbol['end_line']})"
        )

    return "\n".join(lines)

def build_embedding_text(
    chunk: CodeChunk,
) -> str:
    """
    Build metadata-aware text for semantic embedding.

    The embedding includes repository location and symbol metadata
    so semantic retrieval can distinguish similarly worded code.
    """

    lines = [
        f"File: {chunk.file_path}",
    ]

    if chunk.symbol_name:
        lines.append(
            f"Symbol: {chunk.symbol_name}"
        )

    if chunk.symbol_type:
        lines.append(
            f"Type: {chunk.symbol_type}"
        )

    lines.extend(
        [
            "",
            "Code:",
            chunk.content,
        ]
    )

    return "\n".join(lines)

