    self,
    texts: Sequence[str],
) -> list[list[float]]:
    """
    Generate embeddings for multiple repository chunks.

    Rate-limit errors are retried using Gemini's suggested delay
    when available.
    """

    if not texts:
        return []

    cleaned_texts = []

    for text in texts:
        if not text or not text.strip():
            raise ValueError(
                "Document text cannot be empty."
            )

        cleaned_texts.append(text)

    def operation():
        return self.client.models.embed_content(
            model=self.MODEL,
            contents=cleaned_texts,
            config=types.EmbedContentConfig(
                task_type=self.TASK_TYPE,
                output_dimensionality=(
                    self.OUTPUT_DIMENSIONALITY
                ),
            ),
        )

    response = self._with_retry(operation)

    if not response.embeddings:
        raise RuntimeError(
            "Gemini returned no embeddings."
        )

    if len(response.embeddings) != len(
        cleaned_texts
    ):
        raise RuntimeError(
            "Gemini returned an unexpected number "
            "of embeddings."
        )

    embeddings = []

    for embedding in response.embeddings:
        if not embedding.values:
            raise RuntimeError(
                "Gemini returned an empty embedding."
            )

        embeddings.append(
            list(embedding.values)
        )

    return embeddings

